// Local calendar export: no external calendars, accounts or connections.
const text=v=>String(v??'').replace(/\\/g,'\\\\').replace(/\r\n|\r|\n/g,'\\n').replace(/;/g,'\\;').replace(/,/g,'\\,');
const stamp=v=>new Date(v).toISOString().replace(/[-:]/g,'').replace(/\.\d{3}Z$/,'Z');
const compact=d=>d.replaceAll('-','');
function fold(line){const parts=[];let current='',bytes=0;for(const ch of line){const n=new TextEncoder().encode(ch).length;if(bytes+n>75){parts.push(current);current=' ';bytes=1;}current+=ch;bytes+=n;}parts.push(current);return parts.join('\r\n');}
export function plannerCalendar(data,{includeCompleted=true,now=new Date().toISOString()}={}){const lines=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//WIST//Classroom Planner//EN','CALSCALE:GREGORIAN','METHOD:PUBLISH'];for(const day of data.days){for(const row of [...day.deadlines.filter(t=>includeCompleted||!['submitted','returned','feedback'].includes(t.status)).map(t=>({...t,type:'deadline',description:t.className+' · Assignment deadline',date:day.date})),...day.events.filter(e=>e.status==='published').map(e=>({...e,type:'event'}))]){lines.push('BEGIN:VEVENT','UID:'+text(row.type+'-'+row.id+'@wist-classroom'),'DTSTAMP:'+stamp(now),'SUMMARY:'+text(row.title),'DESCRIPTION:'+text((row.className||'')+'\n'+(row.description||'')));if(row.time){const from=Date.parse(row.date+'T'+row.time+':00+05:00');lines.push('DTSTART:'+stamp(from),'DTEND:'+stamp(from+row.duration*60000));}else{const next=new Date(Date.parse(row.date+'T12:00Z')+86400000).toISOString().slice(0,10);lines.push('DTSTART;VALUE=DATE:'+compact(row.date),'DTEND;VALUE=DATE:'+compact(next));}lines.push('END:VEVENT');}}lines.push('END:VCALENDAR');return lines.map(fold).join('\r\n')+'\r\n';}
